import asyncio

n = int(input())
items = []
for _ in range(n):
    parts = input().split()
    items.append((parts[0], parts[1]))

async def attempt(flag, try_no):
    if flag == "ok":
        return True
    if flag == "flaky":
        return try_no >= 2
    return False

async def main():
    delivered = 0
    retries = 0
    failed_ids = []
    for item_id, flag in items:
        done = False
        for try_no in range(1, 4):
            if try_no > 1:
                retries += 1
            ok = await attempt(flag, try_no)
            if ok:
                done = True
                break
        if done:
            delivered += 1
        else:
            failed_ids.append(item_id)
    print("delivered=" + str(delivered))
    print("retries=" + str(retries))
    if failed_ids:
        print("failed " + " ".join(failed_ids))
    else:
        print("failed none")

asyncio.run(main())
